const app=document.querySelector('#app'),modal=document.querySelector('#modal');
let authConfig={neon:false};
let token=sessionStorage.getItem('kpay_token')||'',state=null,page=decodeURIComponent(location.hash.slice(1))||'Dashboard',search='',filter='all',provider='all',index=1,period=7,drawer=false;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'৳ '+((n||0)/100).toLocaleString('en-BD',{minimumFractionDigits:2,maximumFractionDigits:2});
const decimal=n=>((n||0)/100).toFixed(2),mask=n=>n?String(n).slice(0,3)+'••••'+String(n).slice(-4):'—';
const date=v=>v?new Date(v).toLocaleString('en-GB',{timeZone:'Asia/Dhaka',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'Not connected';
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Dhaka'});
const label=v=>({bkash:'bKash',nagad:'Nagad',rocket:'Rocket'}[v]||String(v||'').replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase()));
const badge=s=>`<span class="pill ${esc(s)}">${esc(label(s))}</span>`;
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',card:'M3 5h18v14H3z M3 10h18 M6 15h4',message:'M3 4h18v13H8l-5 4z M7 8h10 M7 12h6',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',wallet:'M3 6h17v14H3z M3 6V3h14v3 M15 11h6v5h-6z',phone:'M7 2h10v20H7z M10 18h4',file:'M5 2h9l5 5v15H5z M14 2v6h5 M8 12h8 M8 16h5',users:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 21v-3c0-4 14-4 14 0v3 M17 4a4 4 0 0 1 0 7 M19 15c3 0 3 4 3 6',user:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M4 22v-3c0-6 16-6 16 0v3',book:'M3 3h7c2 0 2 1 2 2 0-1 0-2 2-2h7v17h-7c-2 0-2 1-2 2 0-1 0-2-2-2H3z M12 5v17',arrow:'M3 12h18 M16 7l5 5-5 5',refresh:'M20 7V3l-3 3 M20 7a8 8 0 1 0 0 10 M20 7h-5',send:'M2 3l20 9-20 9 4-9z M6 12h16',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',check:'M4 12l5 5L20 6',plus:'M12 5v14 M5 12h14',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',chevron:'M9 6l6 6-6 6',close:'M6 6l12 12 M6 18L18 6',logout:'M9 3H3v18h6 M8 12h13 M17 8l4 4-4 4',bell:'M5 17h14l-2-3V8a5 5 0 0 0-10 0v6z M10 21h4',download:'M12 3v13 M7 11l5 5 5-5 M4 16v5h16v-5',alert:'M12 3L2 21h20z M12 9v5 M12 17v1',more:'M5 12h1 M11 12h1 M17 12h1',server:'M3 3h18v7H3z M3 14h18v7H3z M7 6h1 M7 17h1'};
const icon=(name,size=16)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const brand=()=>'<div class="brand"><span class="brand-mark">k</span><span>k<em>Pay</em></span></div>';
const opts=a=>a.map(x=>`<option value="${esc(Array.isArray(x)?x[0]:x)}">${esc(Array.isArray(x)?x[1]:label(x))}</option>`).join('');
const providerOpts=opts([['bkash','bKash'],['nagad','Nagad'],['rocket','Rocket']]);
const typeOpts=opts(['personal','merchant','agent']);
const operationOpts=opts(['incoming_transfer','merchant_payment','agent_collection']);
const input=(text,name,value='',type='text',help='',optional=false)=>`<div class="field"><label for="f-${name}">${text}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${optional?'':'required'} ${type==='password'?'autocomplete="new-password"':''}><small>${help}</small></div>`;
const textarea=(text,name,value='',help='')=>`<div class="field"><label for="f-${name}">${text}</label><textarea id="f-${name}" name="${name}" required>${esc(value)}</textarea><small>${help}</small></div>`;
const select=(text,name,options,value='')=>`<div class="field"><label for="f-${name}">${text}</label><select id="f-${name}" name="${name}" required>${options}</select></div>`;
const hidden=(n,v)=>`<input type="hidden" name="${n}" value="${esc(v)}">`;
const action=(name,text,rid='',kind='secondary',ic='')=>`<button type="button" class="btn ${kind}" data-action="${name}" data-id="${esc(rid)}">${ic?icon(ic,13):''}${text}</button>`;
const rowAction=(name,text,rid)=>action(name,text,rid,'secondary small');
const can=p=>state?.actor.kind==='admin'&&(state.actor.role==='owner'||({operations:['collection','review','evidence'],finance:['finance','merchant','evidence','export'],support:['review']}[state.actor.role]||[]).includes(p));
const byId=(collection,rid)=>state[collection]?.find(x=>x.id===rid);
const accountName=rid=>{const a=byId('accounts',rid);return a?`${a.label||label(a.provider)} · ${mask(a.number)}`:'—';};
const merchantName=rid=>byId('merchants',rid)?.name||rid;
const deviceName=rid=>byId('devices',rid)?.name||'—';
const accountOptions=()=>opts(state.accounts.map(a=>[a.id,`${a.label||label(a.provider)} · ${a.number} (${a.status})`]));
const merchantOptions=()=>opts(state.merchants.map(m=>[m.id,m.name]));
const userOptions=()=>opts(state.users.map(u=>[u.id,u.name+' · '+mask(u.number)]));
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',5000);}
async function api(path,b){const r=await fetch('/api/'+path,{method:b?'POST':'GET',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},...(b?{body:JSON.stringify(b)}:{})});const data=await r.json();if(!r.ok){const e=new Error(data.error||'Request failed');e.status=r.status;throw e;}return data;}
function showModal(title,body,foot='Changes are saved to your local workspace.'){modal.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-button" type="button" data-close aria-label="Close dialog">${icon('close',19)}</button></div><div class="modal-body">${body}</div><div class="modal-foot">${foot}</div>`;modal.querySelector('[data-close]').onclick=()=>modal.close();if(!modal.open)modal.showModal();}
function formModal(title,fields,endpoint,values={},submit='Save changes',after=null){
 showModal(title,`<form id="dialog-form">${fields}<div class="form-error" hidden role="alert"></div><div class="actions"><button class="btn secondary" type="button" data-cancel>Cancel</button><button class="btn" type="submit">${submit} ${icon('arrow',13)}</button></div></form>`);
 const f=modal.querySelector('form');for(const [k,v]of Object.entries(values)){const el=f.elements.namedItem(k);if(el)el.value=v;}
 f.querySelector('[data-cancel]').onclick=()=>modal.close();
 f.onsubmit=async e=>{e.preventDefault();const button=f.querySelector('[type=submit]');button.disabled=true;const error=f.querySelector('.form-error');error.hidden=true;
  try{let b=Object.fromEntries(new FormData(f));if(f.querySelector('[name=providers]'))b.providers=[...f.querySelectorAll('[name=providers]:checked')].map(c=>c.value);const result=await api(endpoint,b);modal.close();await refresh();toast('Saved successfully');if(after)after(result);}catch(e){error.textContent=e.message;error.hidden=false;}finally{button.disabled=false;}
 };
 return f;
}
const reasonField=()=>textarea('Reason / supporting note','reason');
function secretModal(title,key,help){showModal(title,`<p>${help}</p><div class="secret-box">${esc(key)}</div><div class="actions"><button class="btn secondary" id="copy-secret">Copy</button><button class="btn" id="done-secret">Done</button></div>`,'Shown once. Store it securely.');modal.querySelector('#copy-secret').onclick=async()=>{try{await navigator.clipboard.writeText(key);toast('Copied');}catch{toast('Select and copy the value manually');}};modal.querySelector('#done-secret').onclick=()=>modal.close();}
function login(){
 state=null;app.innerHTML=`<div class="login-shell"><section class="login-story">${brand()}<div class="login-pattern"></div><h1>Every payment.<br>One <em>clear picture.</em></h1><p>Your collection accounts, agent devices and payment operations, together in one workspace.</p><small>bKash &nbsp; / &nbsp; Nagad &nbsp; / &nbsp; Rocket</small></section><section class="login-form"><div class="login-box"><div class="login-kicker">Payment operations</div><h2>Welcome to your workspace</h2><p>Sign in to manage your central payment system.</p><form id="login-form">${select('Sign-in method','method',opts(authConfig.neon?[['team','Neon Auth account'],['merchant','Merchant API key']]:[['bootstrap','Workspace owner key'],['team','Team account'],['merchant','Merchant API key']]))}<div id="credentials">${authConfig.neon?input('Email address','email','','email')+input('Password','password','','password'):input('Owner login key','key','','password')}</div>${input('Authenticator code (if enabled)','otp','','text','Six-digit code from your authenticator app.',true)}<div class="form-error" hidden role="alert"></div><button class="btn" type="submit">Sign in to workspace ${icon('arrow',15)}</button>${authConfig.neon?'<button class="btn ghost" type="button" id="register-account">Create invited account</button>':''}</form><div class="login-foot">${authConfig.neon?'Neon Auth · Approved team accounts only':'Local development environment · BDT<br>Owner key is printed in the server terminal.'}</div></div></section></div>`;
 const f=document.querySelector('#login-form');if(authConfig.neon)document.querySelector('#register-account').onclick=async()=>{const button=document.querySelector('#register-account');button.disabled=true;try{const result=await api('register',Object.fromEntries(new FormData(f)));const err=f.querySelector('.form-error');err.textContent=result.message;err.hidden=false;}catch(e){const err=f.querySelector('.form-error');err.textContent=e.message;err.hidden=false;}finally{button.disabled=false;}};f.elements.method.onchange=()=>{if(authConfig.neon)document.querySelector('#register-account').hidden=f.elements.method.value==='merchant';document.querySelector('#credentials').innerHTML=f.elements.method.value==='team'?input('Email address','email','','email')+input('Password','password','','password'):input(f.elements.method.value==='merchant'?'Merchant API key':'Owner login key','key','','password');};
 f.onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(f)),button=f.querySelector('[type=submit]');button.disabled=true;try{const result=await api('login',{...b,role:b.method==='merchant'?'merchant':'admin'});token=result.token||'';if(token)sessionStorage.setItem('kpay_token',token);else sessionStorage.removeItem('kpay_token');page='Dashboard';await refresh();}catch(e){const err=f.querySelector('.form-error');err.textContent=e.message;err.hidden=false;}finally{button.disabled=false;}};
}
async function refresh(silent=false){try{state=await api('state');render();}catch(e){if(e.status===401){token='';sessionStorage.removeItem('kpay_token');login();if(!silent)toast(e.message);}else{app.innerHTML=`<div class="main"><div class="error-view"><h2>Workspace could not load</h2><p>${esc(e.message)}</p><button class="btn" id="reload">Try again</button></div></div>`;document.querySelector('#reload').onclick=refresh;}}}
const navigation=[['Workspace',[['Dashboard','grid'],['Payments','card'],['Incoming SMS','message'],['Review queue','shield']]],['Collection setup',[['Receiving accounts','wallet'],['Agent devices','phone'],['SMS templates','file']]],['Business & finance',[['Merchants','users'],['Recharge users','user'],['Ledger','book'],['Settlements','send']]],['System',[['Webhook deliveries','refresh'],['Audit log','clock'],['Administrators','shield'],['Settings','settings']]]];
const descriptions={'Dashboard':'A clear view of your collection activity and operations.','Payments':'Track customer payments, receipt matches and approvals.','Incoming SMS':'Inspect messages received from your enrolled collection phones.','Review queue':'Investigate unmatched payments and conflicting evidence.','Receiving accounts':'Your centrally managed payment collection numbers.','Agent devices':'Connect, approve and monitor your collection phones.','SMS templates':'Teach kPay how to recognize incoming payment messages.','Merchants':'Manage integrations, merchant access and available balances.','Recharge users':'Track users and their verified recharge balances.','Ledger':'An immutable record of credits, reservations and settlements.','Settlements':'Prepare and approve payouts from available merchant balances.','Webhook deliveries':'Monitor signed payment events sent to merchant websites.','Audit log':'A traceable history of workspace actions.','Administrators':'Manage your operations team and permission roles.','Settings':'Configure collection policies, limits and fees.'};
function go(next){page=next;search='';filter='all';provider='all';index=1;drawer=false;location.hash=next;render();}
function pageTools(){const map={'Receiving accounts':['new-account','Add account','collection'],'Agent devices':['new-device','Pair device','collection'],'SMS templates':['new-template','New template','collection'],'Merchants':['new-merchant','Add merchant','merchant'],'Recharge users':['new-user','Add user','merchant'],'Payments':['new-payment','Create test payment','collection'],'Settlements':['new-settlement','Prepare settlement','finance'],'Administrators':['new-admin','Add administrator','*'],'Ledger':['export-ledger','Export CSV','export']};const t=map[page];return t&&can(t[2])?action(t[0],t[1],'','',t[0]==='export-ledger'?'download':'plus'):'';}
function render(){
 if(!state)return;const isAdmin=state.actor.kind==='admin';if(!descriptions[page]||(!isAdmin&&!['Dashboard','Payments','Merchants','Settlements'].includes(page)))page='Dashboard';
 const openReviews=state.reviews?.filter(r=>r.status==='open').length||0;
 const nav=navigation.map(([group,items])=>{const available=items.filter(([p])=>isAdmin?(p!=='Administrators'||state.actor.role==='owner'):['Dashboard','Payments','Merchants','Settlements'].includes(p));return available.length?`<div class="nav-group">${group}</div>${available.map(([p,ic])=>`<button data-page="${p}" class="${p===page?'active':''}" ${p===page?'aria-current="page"':''}>${icon(ic)}<span>${p}</span>${p==='Review queue'&&openReviews?`<span class="nav-count">${openReviews}</span>`:''}</button>`).join('')}`:'';}).join('');
 app.innerHTML=`<aside class="sidebar ${drawer?'open':''}">${brand()}<div class="workspace-label">${isAdmin?'Administration':'Merchant workspace'} ${icon('chevron',12)}</div><nav class="nav" aria-label="Main navigation">${nav}</nav><div class="sidebar-footer"><div class="avatar">${esc(state.actor.name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase())}</div><div><strong>${esc(state.actor.name)}</strong><small>${esc(label(state.actor.role))}</small></div>${isAdmin?'<button class="icon-button" data-action="account-security" aria-label="Account security">'+icon('shield',17)+'</button>':''}<button id="logout" class="icon-button" aria-label="Sign out">${icon('logout',17)}</button></div></aside><div class="shell"><header class="topbar"><div class="row"><button class="icon-button mobile-menu" id="menu" aria-label="Toggle navigation">${icon('more',20)}</button><div class="breadcrumb">Workspace <span>/ &nbsp; ${esc(page)}</span></div></div><div class="topbar-right"><div class="sandbox"><i class="dot"></i> LOCAL SANDBOX</div><div class="top-divider"></div><small class="date-label">${new Date().toLocaleDateString('en-GB',{timeZone:'Asia/Dhaka',day:'numeric',month:'short',year:'numeric'})}</small><button class="icon-button" data-page="Review queue" aria-label="Open review alerts">${icon('bell',18)}</button></div></header><main class="main"><div class="page-heading"><div><h1>${esc(page)}</h1><p>${descriptions[page]}</p></div><div class="actions">${action('refresh','Refresh','','secondary','refresh')}${pageTools()}</div></div>${content()}<footer class="footer"><span>kPay · Central payment operations</span><span>BDT · Asia/Dhaka &nbsp; / &nbsp; Local development</span></footer></main></div>`;
 bind();
}
function empty(title,description){return `<div class="empty">${icon('file',27)}<strong>${title}</strong><p>${description}</p></div>`;}
function table(title,heads,records,rowBuilder,{hint='',statuses=[],providers=false}={}){
 const list=records.filter(r=>(filter==='all'||r.status===filter)&&(provider==='all'||r.provider===provider||byId('accounts',r.account_id)?.provider===provider)&&JSON.stringify(r).toLowerCase().includes(search.toLowerCase()));
 const count=Math.max(1,Math.ceil(list.length/8));index=Math.min(index,count);const slice=list.slice((index-1)*8,index*8);
 return `<section class="panel"><div class="panel-heading"><div><h2>${title}</h2><p>${hint||'Manage and inspect your workspace records.'}</p></div><small>${records.length} total</small></div><div class="toolbar"><div class="search">${icon('search',14)}<input id="list-search" aria-label="Search records" placeholder="Search records…" value="${esc(search)}"></div><div class="filters">${providers?`<select id="provider-filter" aria-label="Filter by provider"><option value="all">All providers</option>${providerOpts}</select>`:''}${statuses.length?`<select id="status-filter" aria-label="Filter by status"><option value="all">All statuses</option>${opts(statuses)}</select>`:''}</div></div><div class="wide"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${slice.map(rowBuilder).join('')}</tbody></table></div>${!slice.length?empty(records.length?'No matching records':'No records yet',records.length?'Try another search or filter.':'Add your first record to begin. All activity will appear here.'):''}<div class="pagination"><span>${list.length?`${(index-1)*8+1}–${Math.min(index*8,list.length)}`:'0'} of ${list.length} records</span><div class="actions"><button class="btn secondary small" data-paginate="-1" ${index===1?'disabled':''}>Previous</button><span>Page ${index} of ${count}</span><button class="btn secondary small" data-paginate="1" ${index===count?'disabled':''}>Next</button></div></div></section>`;
}
const td=(...cells)=>'<tr>'+cells.map(c=>'<td>'+c+'</td>').join('')+'</tr>';
const detail=(type,rid)=>rowAction('detail-'+type,'View',rid);
function paymentRow(p){const a=byId('accounts',p.account_id);return td(`<strong>${esc(p.order_id)}</strong><small>${date(p.created)}</small>`,`<strong>${esc(p.beneficiary_type==='user'?byId('users',p.beneficiary_id)?.name||'Recharge user':merchantName(p.merchant))}</strong><small>${p.beneficiary_type==='user'?'User recharge':'Merchant collection'}</small>`,`${esc(label(a?.provider))}<small>${esc(mask(a?.number))}</small>`,money(p.amount),`${esc(p.trx||'Awaiting details')}<small>${esc(mask(p.sender))}</small>`,badge(p.status),detail('payments',p.id));}
function dashboard(){
 const verified=state.payments.filter(p=>p.status==='verified'),gross=verified.reduce((s,p)=>s+p.amount,0),pending=state.payments.filter(p=>p.status==='pending').length,unmatched=state.receipts?.filter(r=>!r.payment_id).length||0;
 const active=state.accounts.filter(a=>a.status==='active').length;
 const metrics=[['Total collected',money(gross),'From verified payments','wallet'],['Verified payments',verified.length,'Matched against receipt evidence','check'],['Awaiting payment',pending,'Pending customer payment requests','clock'],['Active accounts',`${active} / ${state.accounts.length}`,'Centrally managed collection','phone']];
 const days=Array.from({length:period},(_,i)=>{const d=new Date(Date.now()-(period-1-i)*86400000);const key=d.toLocaleDateString('en-CA',{timeZone:'Asia/Dhaka'});return {label:d.toLocaleDateString('en-GB',{timeZone:'Asia/Dhaka',day:'numeric',month:'short'}),amount:verified.filter(p=>new Date(p.created).toLocaleDateString('en-CA',{timeZone:'Asia/Dhaka'})===key).reduce((s,p)=>s+p.amount,0)};});const max=Math.max(10000,...days.map(d=>d.amount));
 return `<div class="metrics">${metrics.map(([name,value,help,ic])=>`<div class="metric"><div class="metric-top">${name}<span class="metric-icon">${icon(ic,15)}</span></div><div class="metric-value">${value}</div><div class="metric-foot"><span class="dot"></span>${help}</div></div>`).join('')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><h2>Collection overview</h2><p>Verified collection across all payment providers</p></div><div class="period-control"><button data-period="7" class="${period===7?'active':''}">7 days</button><button data-period="14" class="${period===14?'active':''}">14 days</button></div></div><div class="panel-body"><div class="chart"><div class="chart-labels">${[1,.75,.5,.25,0].map(x=>`<span>${money(max*x)}</span>`).join('')}</div><div class="chart-lines">${Array(5).fill('<div class="chart-line"></div>').join('')}</div><div class="chart-bars">${days.map(d=>`<div class="chart-bar" title="${esc(d.label)} · ${money(d.amount)}"><span>${esc(d.label)}</span></div>`).join('')}</div>${days.every(d=>d.amount===0)?'<div class="chart-empty">Your first verified payment will appear here</div>':''}</div><div class="chart-key"><i></i> Collected amount (BDT)</div></div></section><section class="panel"><div class="panel-heading"><div><h2>Payment providers</h2><p>Collection by payment platform</p></div>${icon('wallet',17)}</div><div class="panel-body">${['bkash','nagad','rocket'].map(pr=>{const ps=verified.filter(p=>byId('accounts',p.account_id)?.provider===pr);return `<div class="provider-line"><span class="provider-symbol ${pr}">${pr==='bkash'?'b':pr==='nagad'?'N':'R'}</span><div class="provider-info"><strong>${pr==='bkash'?'bKash':label(pr)}</strong><small>${state.accounts.filter(a=>a.provider===pr&&a.status==='active').length} active accounts</small></div><div class="provider-total"><strong>${money(ps.reduce((s,p)=>s+p.amount,0))}</strong><small>${ps.length} verified payments</small></div></div>`;}).join('')}<div class="health-row"><strong>Currency</strong><small>Bangladeshi taka · BDT</small></div></div></section></div>${state.actor.kind==='admin'?`<div class="split"><section class="panel"><div class="panel-heading"><h2>Needs attention</h2>${rowAction('goto-review','View queue','')}</div><div class="panel-body">${[['Unmatched receipts',unmatched,'Receipts waiting for customer claims','Incoming SMS'],['Open review cases',state.reviews.filter(r=>r.status==='open').length,'Payment evidence requiring investigation','Review queue'],['Device health',state.devices.filter(d=>d.status==='active'&&(!d.last_seen||Date.now()-Date.parse(d.last_seen)>state.settings.offline_minutes*60000)).length,'Approved phones that have stopped reporting','Agent devices']].map(([name,count,desc,dest])=>`<div class="alert-row"><div class="alert-icon">${icon(count?'alert':'check',15)}</div><div><strong>${name} <span class="muted">(${count})</span></strong><p>${desc}</p></div><button class="btn secondary small" data-page="${dest}" aria-label="Open ${dest}">${icon('chevron',12)}</button></div>`).join('')}</div></section><section class="panel"><div class="panel-heading"><h2>System status</h2><span class="pill active">Local workspace</span></div><div class="panel-body"><div class="health-row">${icon('server',16)}<strong>Backend & storage</strong>${badge('active')}</div><div class="health-row">${icon('phone',16)}<strong>Approved collection devices</strong><small>${state.devices.filter(d=>d.status==='active').length} / ${state.devices.length}</small></div><div class="health-row">${icon('file',16)}<strong>Published SMS formats</strong><small>${state.templates.filter(t=>t.status==='published').length} templates</small></div></div></section></div>`:''}<section class="panel"><div class="panel-heading"><div><h2>Recent payments</h2><p>The latest activity across your collection accounts</p></div><button class="text-button" data-page="Payments">View all payments →</button></div><div class="wide"><table><thead><tr>${['Order','Beneficiary','Provider','Amount','Transaction','Status',''].map(x=>'<th>'+x+'</th>').join('')}</tr></thead><tbody>${state.payments.slice(0,5).map(paymentRow).join('')}</tbody></table></div>${!state.payments.length?empty('Ready for your first payment','Configure a receiving account, publish an SMS template and enroll a collection device.'):''}</section>${!state.accounts.length&&can('collection')?`<section class="panel"><div class="panel-heading"><div><h2>Set up your collection workspace</h2><p>Three steps to start testing payment verification</p></div><span class="pill draft">Getting started</span></div><div class="panel-body steps">${[['1','Add a central account','Choose a provider, account type and receiving number.','new-account','Add account'],['2','Publish an SMS template','Save samples and test sender, transaction and amount extraction.','new-template','Create template'],['3','Pair a collection phone','Enroll and approve the device before account activation.','new-device','Pair device']].map(([n,title,text,a,b])=>`<div class="step"><span class="step-num">${n}</span><h3>${title}</h3><p>${text}</p>${action(a,b,'','secondary small')}</div>`).join('')}</div></section>`:''}`;
}
function content(){
 if(page==='Dashboard')return dashboard();
 if(page==='Payments')return `<div class="stat-chips"><div class="stat-chip">Verified <strong>${state.payments.filter(p=>p.status==='verified').length}</strong></div><div class="stat-chip">Pending <strong>${state.payments.filter(p=>p.status==='pending').length}</strong></div><div class="stat-chip">Needs review <strong>${state.payments.filter(p=>p.status==='review_required').length}</strong></div></div>${table('Payment requests',['Order','Beneficiary','Provider','Amount','Transaction','Status','Actions'],state.payments,paymentRow,{statuses:['pending','verified','review_required','rejected'],providers:true})}`;
 if(page==='Receiving accounts')return `<div class="info-strip">${icon('shield',16)}Receiving numbers are centrally managed. Activation requires a published template and approved, healthy collection device.</div>${table('Collection accounts',['Account','Provider / type','Operation','Amount limits','Status','Actions'],state.accounts,a=>td(`<strong>${esc(a.label)}</strong><small>${esc(mask(a.number))}</small>`,`${esc(label(a.provider))}<small>${esc(label(a.type))}</small>`,esc(label(a.operation)),`${money(a.minimum)} – ${money(a.maximum)}<small>Daily cap ${money(a.daily_limit)}</small>`,badge(a.status),`<div class="table-actions">${detail('accounts',a.id)}${can('collection')?rowAction('edit-account','Edit',a.id)+rowAction('account-status','Status',a.id):''}</div>`),{statuses:['active','paused','quarantined','retired'],providers:true})}`;
 if(page==='Agent devices')return `<div class="info-strip">${icon('phone',16)}Create a one-use pairing code, enroll the agent, then approve its SIM/account binding. The local simulator is available for testing.</div>${table('Collection phones',['Device','Linked account','SIM binding','Last seen','SMS / queue','Status','Actions'],state.devices,d=>td(`<strong>${esc(d.name)}</strong><small>${esc(d.app_version||'Not enrolled')} · ${esc(d.android_version||'—')}</small>`,esc(accountName(d.account_id)),esc(d.sim)+(d.public_key?'<small>Subscription '+esc(d.proposed_subscription??'Pending')+' · '+esc(d.binding_health)+'</small>':''),date(d.last_seen),`${esc(label(d.permission))}<small>${d.queue_depth} queued messages</small>`,badge(d.status),`<div class="table-actions">${detail('devices',d.id)}${can('collection')?rowAction('device-status','Manage',d.id):''}</div>`),{statuses:['pending','active','paused','revoked']})}<section class="panel"><div class="panel-heading"><div><h2>Development simulator</h2><p>Exercise the enrollment and ingestion endpoints without a phone.</p></div></div><div class="panel-body">${can('collection')?action('sim-enroll','Enroll with pairing code','','secondary','phone')+' '+action('sim-sms','Upload test SMS','','secondary','message'):''}<p class="subtitle">Simulation does not capture real SMS. Install the Android agent APK for real SMS collection.</p></div></section>`;
 if(page==='SMS templates')return `<div class="info-strip">${icon('file',16)}Use {{sender}}, {{transaction}} and {{amount}} markers. Publication requires two distinct positive samples and a negative sample.</div>${table('Payment SMS formats',['Template','Provider / type','SMS origin','Version','Status','Actions'],state.templates,t=>td(`<strong>${esc(t.name)}</strong><small>${esc(label(t.operation))}</small>`,`${esc(label(t.provider))}<small>${esc(label(t.type))}</small>`,esc(t.sms_sender),'v'+t.version,badge(t.status),`<div class="table-actions">${detail('templates',t.id)}${can('collection')?rowAction('template-fixture','Samples',t.id)+rowAction('template-publish',t.status==='published'?'Pause':'Publish',t.id)+rowAction('template-clone','New version',t.id):''}</div>`),{statuses:['draft','published','paused'],providers:true})}`;
 if(page==='Incoming SMS')return `<div class="info-strip">${icon('shield',16)}Raw message content is restricted. Revealing evidence creates an audit record.</div>${table('Incoming messages',['Received','Device / account','SMS origin','Result','Evidence','Actions'],state.sms,s=>td(date(s.created),`<strong>${esc(deviceName(s.device_id))}</strong><small>${esc(accountName(s.account_id))}</small>`,esc(s.sms_sender),badge(s.status),esc(s.reason||'Payment fields extracted'),can('evidence')?detail('sms',s.id):'Restricted'),{statuses:['parsed','unparsed','duplicate','conflict','ambiguous','quarantined'],providers:true})}<section class="panel"><div class="panel-heading"><h2>Normalized receipts</h2><small>${state.receipts.length} total</small></div><div class="wide"><table><thead><tr><th>Transaction ID</th><th>Provider</th><th>Sender</th><th>Amount</th><th>Status</th></tr></thead><tbody>${state.receipts.map(r=>td(esc(r.trx),esc(label(r.provider)),esc(mask(r.sender)),money(r.amount),badge(r.payment_id?'matched':r.status))).join('')}</tbody></table></div>${!state.receipts.length?empty('No payment receipts yet','Eligible incoming SMS will produce a receipt here.'):''}</section>`;
 if(page==='Review queue')return table('Payment investigations',['Case','Category','Entity','Assigned','Status','Actions'],state.reviews,r=>td(`<strong>${esc(r.id.slice(0,8))}</strong><small>${date(r.created)}</small>`,esc(r.category),esc(label(r.entity_type)),esc(state.administrators.find(a=>a.id===r.assignee)?.name||r.assignee||'Unassigned'),badge(r.status),rowAction('review','Investigate',r.id)),{statuses:['open','resolved']});
 if(page==='Merchants')return table('Merchant accounts',['Merchant','Enabled providers','Available balance','Reserved','Status','Actions'],state.merchants,m=>td(`<strong>${esc(m.name)}</strong><small>${esc(m.email)}</small>`,esc(JSON.parse(m.providers).map(label).join(', ')),money(m.available),money(m.reserved),badge(m.status),`<div class="table-actions">${detail('merchants',m.id)}${can('merchant')?rowAction('merchant-status','Manage',m.id)+rowAction('webhook-config','Webhook',m.id)+rowAction('destination-request','Destination',m.id):''}${can('*')?rowAction('merchant-key','API key',m.id):''}</div>`),{statuses:['active','suspended']})+`<section class="panel"><div class="panel-heading"><div><h2>Settlement destination approvals</h2><p>A different administrator must verify changes before payouts.</p></div></div><div class="wide"><table><thead><tr><th>Merchant</th><th>Destination</th><th>Status</th><th>Action</th></tr></thead><tbody>${(state.destination_requests||[]).map(d=>td(esc(merchantName(d.merchant_id)),esc(d.destination),badge(d.status),d.status==='requested'&&can('merchant')?rowAction('destination-approve','Approve',d.id):'—')).join('')}</tbody></table></div>${!(state.destination_requests||[]).length?empty('No destination requests','Changes are independently approved before settlement.'):''}</section>`;
 if(page==='Recharge users')return `<div class="info-strip">${icon('wallet',16)}User balances are derived from verified recharge ledger entries. Direct balance editing and cash withdrawals are disabled.</div>${table('Recharge users',['User','Mobile number','Available balance','Status','Actions'],state.users,u=>td(`<strong>${esc(u.name)}</strong><small>${date(u.created)}</small>`,esc(mask(u.number)),money(u.balance),badge(u.status),`<div class="table-actions">${detail('users',u.id)}${can('merchant')?rowAction('user-status','Status',u.id):''}${can('collection')?rowAction('new-recharge','Test recharge',u.id):''}</div>`),{statuses:['active','suspended']})}`;
 if(page==='Ledger')return `${table('Ledger postings',['Posted','Description','Type','Source','Actions'],state.ledger,l=>td(date(l.created),`<strong>${esc(l.description)}</strong>`,badge(l.kind),`<code>${esc(l.source.slice(0,30))}…</code>`,detail('ledger',l.id)),{hint:'Each posting is balanced and linked to its immutable source.'})}<div class="split"><section class="panel"><div class="panel-heading"><div><h2>Reconciliation</h2><p>Compare statement totals with received payment evidence.</p></div>${can('finance')?action('new-reconciliation','Record','','secondary small'):''}</div><div class="wide"><table><thead><tr><th>Day / account</th><th>Statement</th><th>Receipts</th><th>Variance</th></tr></thead><tbody>${state.reconciliation.map(r=>td(`${esc(r.day)}<small>${esc(accountName(r.account_id))}</small>`,money(r.statement_amount),money(r.receipt_amount),money(r.variance))).join('')}</tbody></table></div>${!state.reconciliation.length?empty('No reconciliation recorded','Record a statement comparison after collection testing.'):''}</section><section class="panel"><div class="panel-heading"><div><h2>Finance adjustments</h2><p>Requests require a different administrator to approve.</p></div>${can('finance')?action('new-adjustment','Request','','secondary small'):''}</div><div class="wide"><table><thead><tr><th>Merchant</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody>${state.adjustments.map(a=>td(esc(merchantName(a.merchant_id)),money(a.amount),badge(a.status),a.status==='requested'&&can('finance')?rowAction('adjustment-approve','Approve',a.id):'—')).join('')}</tbody></table></div>${!state.adjustments.length?empty('No adjustments','Payment balances are updated through ledger postings.'):''}</section></div>`;
 if(page==='Settlements')return `<div class="info-strip warning">${icon('shield',16)}Payouts require separate preparation and approval. This panel records external payout evidence; it does not transfer funds.</div>${table('Merchant payouts',['Merchant / created','Payout amount','Destination','Maker / checker','Status','Actions'],state.settlements,s=>td(`<strong>${esc(merchantName(s.merchant_id))}</strong><small>${date(s.created)}</small>`,money(s.amount),esc(s.destination),`${esc(state.administrators?.find(a=>a.id===s.maker)?.name||s.maker)}<small>${esc(state.administrators?.find(a=>a.id===s.checker)?.name||s.checker||'Awaiting approval')}</small>`,badge(s.status),`<div class="table-actions">${detail('settlements',s.id)}${can('finance')&&['reserved','approved','uncertain'].includes(s.status)?rowAction('settlement-action','Manage',s.id):''}</div>`),{statuses:['reserved','approved','paid','cancelled','uncertain','failed']})}`;
 if(page==='Webhook deliveries')return `<div class="info-strip">${icon('send',16)}Signed events keep a stable event ID across retries. Configure a merchant's public HTTPS endpoint from the Merchants page.</div>${table('Event deliveries',['Event','Merchant','Attempts','Last HTTP','Status / error','Actions'],state.webhooks,w=>td(`<strong>${esc(w.event)}</strong><small>${date(w.created)}</small>`,esc(merchantName(w.merchant_id)),String(w.attempts),String(w.last_status||'—'),`${badge(w.status)}<small>${esc(w.last_error)}</small>`,can('merchant')?rowAction('webhook-retry','Redeliver',w.id):'—'),{statuses:['queued','delivered','failed']})}`;
 if(page==='Audit log')return table('Workspace audit trail',['Time','Actor / role','Action','Entity','Reason'],state.audit,a=>td(date(a.created),`${esc(state.administrators.find(x=>x.id===a.actor)?.name||a.actor)}<small>${esc(label(a.role))}</small>`,esc(a.event),`<code>${esc(a.entity?.slice(0,20)||'—')}</code>`,esc(a.reason||'—')),{hint:'Read-only history. Credential values and raw evidence are not included.'});
 if(page==='Administrators')return `${table('Operations team',['Administrator','Email','Role','Status','Actions'],state.administrators,a=>td(`<strong>${esc(a.name)}</strong><small>${date(a.created)}</small>`,esc(a.email),esc(label(a.role)),badge(a.status),a.id!==state.actor.id?rowAction('admin-status','Status',a.id):'<small>Current session</small>'),{statuses:['active','suspended']})}<section class="panel"><div class="panel-heading"><h2>Permission roles</h2></div><div class="panel-body"><div class="detail-grid">${[['Owner','All workspace configuration, administrators and finance approval.'],['Operations','Receiving accounts, devices, templates and payment investigations.'],['Finance','Merchant management, ledger exports and payout preparation/approval.'],['Support','Read-only masked payment information and investigation notes.']].map(([r,t])=>`<div class="detail-field"><span>${r}</span><strong>${t}</strong></div>`).join('')}</div></div></section>`;
 if(page==='Settings')return `<section class="panel form-card"><h2>Collection policy</h2><p class="subtitle">Changes affect new requests. Payment fee snapshots and historical evidence remain unchanged.</p><form id="settings-form">${hidden('version',state.settings.version)}<div class="settings-grid">${input('Organization name','organization',state.settings.organization)}${input('Payment expiry (minutes)','expiry_minutes',state.settings.expiry_minutes,'number','5–1,440 minutes')}${input('Review window (days)','review_days',state.settings.review_days,'number','1–90 days; operator review policy')}${input('Device offline threshold (minutes)','offline_minutes',state.settings.offline_minutes,'number','New allocation requires a fresh healthy device heartbeat')}${input('Raw SMS retention policy (days)','raw_retention_days',state.settings.raw_retention_days,'number','Policy value; automatic purge is not enabled in this local release')}${input('Merchant fee (basis points)','fee_bps',state.settings.fee_bps,'number','100 basis points = 1%')}${input('Fixed fee (poisha)','fee_fixed',state.settings.fee_fixed,'number','100 poisha = ৳1')}${input('Change reason','reason')}</div><div class="form-error" hidden></div>${can('*')?'<button class="btn" type="submit">Save policy '+icon('check',14)+'</button>':'<div class="info-strip">Only workspace owners can change policy.</div>'}</form></section><div class="info-strip warning">${icon('shield',16)}Local development release. Enable MFA for all privileged administrators before production. Managed device signing, encrypted evidence and PostgreSQL deployment remain launch prerequisites.</div>`;
 return '';
}
function bind(){
 document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));document.querySelector('#logout').onclick=async()=>{try{await api('logout',{});}catch{}token='';sessionStorage.removeItem('kpay_token');login();};
 document.querySelector('#menu').onclick=()=>{drawer=!drawer;document.querySelector('.sidebar').classList.toggle('open',drawer);};
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action,b.dataset.id).catch(e=>toast(e.message)));
 const s=document.querySelector('#list-search');if(s)s.oninput=()=>{const caret=s.selectionStart;search=s.value;index=1;render();const next=document.querySelector('#list-search');next.focus();next.setSelectionRange(caret,caret);};
 const f=document.querySelector('#status-filter');if(f){f.value=filter;f.onchange=()=>{filter=f.value;index=1;render();};}const pr=document.querySelector('#provider-filter');if(pr){pr.value=provider;pr.onchange=()=>{provider=pr.value;index=1;render();};}
 document.querySelectorAll('[data-paginate]').forEach(b=>b.onclick=()=>{index+=Number(b.dataset.paginate);render();});document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{period=Number(b.dataset.period);render();});
 const settingsForm=document.querySelector('#settings-form');if(settingsForm)settingsForm.onsubmit=async e=>{e.preventDefault();const btn=settingsForm.querySelector('[type=submit]');if(!btn)return;btn.disabled=true;try{await api('admin/settings',Object.fromEntries(new FormData(settingsForm)));await refresh();toast('Collection policy saved');}catch(e){const err=settingsForm.querySelector('.form-error');err.textContent=e.message;err.hidden=false;}finally{btn.disabled=false;}};
 // CSP-safe chart height assignment through the CSSOM.
 document.querySelectorAll('.chart-bar').forEach((bar,i)=>{const visible=state.payments.filter(p=>p.status==='verified');const ds=Array.from({length:period},(_,j)=>new Date(Date.now()-(period-1-j)*86400000).toLocaleDateString('en-CA',{timeZone:'Asia/Dhaka'}));const totals=ds.map(d=>visible.filter(p=>new Date(p.created).toLocaleDateString('en-CA',{timeZone:'Asia/Dhaka'})===d).reduce((s,p)=>s+p.amount,0));bar.style.height=Math.max(1,totals[i]/Math.max(1,...totals)*100)+'%';});
}
async function handleAction(a,rid){
 if(a==='refresh')return refresh();if(a==='goto-review')return go('Review queue');
 if(a.startsWith('detail-'))return viewDetail(a.slice(7),rid);
 if(a==='new-account')return formModal('Add central receiving account',`<div class="form-grid">${input('Account label','label')}${input('Receiving number','number','','tel')}${select('Provider','provider',providerOpts)}${select('Account type','type',typeOpts)}${select('Incoming payment operation','operation',operationOpts)}${input('Minimum amount (BDT)','minimum','1.00')}${input('Maximum amount (BDT)','maximum','100000.00')}${input('Daily allocation cap (BDT)','daily_limit','1000000.00')}</div>${textarea('Customer payment instructions','instructions','','Describe the exact operation customers must use for this account.')}`,'admin/accounts',{},'Add account');
 if(a==='edit-account'){const r=byId('accounts',rid);return formModal('Edit collection account',hidden('version',r.version)+input('Account label','label',r.label)+textarea('Checkout instructions','instructions',r.instructions)+`<div class="form-grid">${input('Minimum (BDT)','minimum',decimal(r.minimum))}${input('Maximum (BDT)','maximum',decimal(r.maximum))}${input('Daily cap (BDT)','daily_limit',decimal(r.daily_limit))}</div>`+reasonField(),'admin/accounts/'+rid);}
 if(a==='account-status'){const r=byId('accounts',rid);return formModal('Change account status',hidden('version',r.version)+hidden('action','status')+select('Account status','status',opts(['active','paused','quarantined','retired']))+reasonField(),'admin/accounts/'+rid,{status:r.status});}
 if(a==='new-device'){if(!state.accounts.length)throw new Error('Add a central receiving account first');return formModal('Pair a collection device',input('Device name','name')+select('Central receiving account','account_id',accountOptions())+input('SIM binding label','sim','','text','Identify the physical collection SIM, e.g. SIM 1 / collection number.'),'admin/devices',{},'Generate pairing code',r=>secretModal('One-use device pairing code',r.code,'Expires in 10 minutes. Enter this code in the agent app or local enrollment simulator.'));}
 if(a==='device-status'){const d=byId('devices',rid);return formModal('Manage '+d.name,hidden('version',d.version)+select('Action','action',opts([['status','Change device status'],['pair','Re-pair / rotate credential'],['refresh','Request configuration refresh']]))+select('Device status','status',opts(['active','paused','revoked']))+(d.public_key?input('Confirm phone subscription ID','subscription_id',String(d.proposed_subscription??''),'number','Check this ID against the physical collection SIM on the phone.'):'')+reasonField(),'admin/devices/'+rid,{status:d.status==='pending'?'active':d.status},'Apply action',r=>{if(r.code)secretModal('New pairing code',r.code,'Enroll again to rotate the device credential.');});}
 if(a==='sim-enroll')return formModal('Enroll simulated collection device',`<div class="info-strip warning">This development helper reports simulated SMS permission. It is not a native Android enrollment.</div>${input('One-use pairing code','code')}${input('App version','app_version','simulator-1.0')}${input('Android version','android_version','Simulator')}`,'admin/simulator/enroll',{},'Enroll simulator',r=>secretModal('Device test credential',r.key,'Shown once for local API tests. Approve this device from its Manage action next.'));
 if(a==='sim-sms')return formModal('Upload a test payment SMS',select('Receiving account','account_id',accountOptions())+input('Client event ID','client_event_id',crypto.randomUUID())+input('SMS originating address','sms_sender')+textarea('Payment SMS body','message'),'admin/simulator/receipts',{},'Upload evidence',r=>toast(r.status==='parsed'?'Receipt parsed and matching attempted':r.reason||label(r.status)));
 if(a==='new-template'||a==='template-clone'){
  const parent=a==='template-clone'?byId('templates',rid):null;
  const f=formModal(parent?'Create new template version':'Create SMS template',`${parent?hidden('parent_id',parent.id):''}<div class="form-grid">${input('Template name','name',parent?.name||'')}${input('SMS originating address','sms_sender',parent?.sms_sender||'')}${select('Provider','provider',providerOpts)}${select('Account type','type',typeOpts)}${select('Incoming operation','operation',operationOpts)}</div>${textarea('Positive sample SMS','sample',parent?.sample||'')}${textarea('Matching template','pattern',parent?.pattern||'','Select text to replace with a field marker. All three fields are required.')}<div class="editor-tools">${['sender','transaction','amount'].map(n=>`<button class="btn soft small" type="button" data-marker="${n}">{{${n}}}</button>`).join('')}<button class="btn secondary small" type="button" id="test-pattern">Test extraction</button></div><div id="parse-preview"></div>`,'admin/templates',parent?{provider:parent.provider,type:parent.type,operation:parent.operation}:{},'Save draft');
  f.querySelectorAll('[data-marker]').forEach(b=>b.onclick=()=>{const t=f.elements.pattern;const start=t.selectionStart,end=t.selectionEnd;t.value=t.value.slice(0,start)+'{{'+b.dataset.marker+'}}'+t.value.slice(end);t.focus();});f.querySelector('#test-pattern').onclick=async()=>{try{const d=await api('admin/templates/test',{pattern:f.elements.pattern.value,sample:f.elements.sample.value});f.querySelector('#parse-preview').innerHTML=`<div class="preview-grid"><div><span>Sender</span><strong>${esc(d.sender)}</strong></div><div><span>Transaction</span><strong>${esc(d.transaction)}</strong></div><div><span>Amount</span><strong>${money(d.amount)}</strong></div></div>`;}catch(e){f.querySelector('#parse-preview').innerHTML='<div class="form-error">'+esc(e.message)+'</div>';}};return;
 }
 if(a==='template-fixture'){const t=byId('templates',rid);if(t.status!=='draft')return viewDetail('templates',rid);return formModal('Add template test sample',textarea('SMS sample','message')+select('Expected result','expected',opts([['match','Positive — must extract payment fields'],['reject','Negative — must not match']])),'admin/templates/'+rid+'/fixtures',{},'Save test sample',results=>showModal('Fixture test results',results.map(f=>`<div class="note">${badge(f.passed?'verified':'failed')} ${esc(label(f.expected))}<pre>${esc(f.message)}</pre>${f.error?'<small>'+esc(f.error)+'</small>':''}</div>`).join('')));}
 if(a==='template-publish'){const t=byId('templates',rid);return formModal(t.status==='published'?'Pause SMS template':'Publish tested SMS template',`<p>Publishing activates this immutable version and pauses other published versions in its family.</p>${reasonField()}`,'admin/templates/'+rid+'/'+(t.status==='published'?'pause':'publish'));}
 if(a==='new-merchant')return formModal('Onboard merchant',input('Merchant name','name')+input('Contact email','email','','email')+input('Approved settlement destination','destination','','text','Record the destination after administrator verification.'),'admin/merchants');
 if(a==='merchant-status'){const m=byId('merchants',rid);return formModal('Manage merchant',hidden('version',m.version)+select('Merchant status','status',opts(['active','suspended']))+`<div class="field"><label>Enabled providers</label><div class="checks">${['bkash','nagad','rocket'].map(p=>`<label><input type="checkbox" name="providers" value="${p}" ${JSON.parse(m.providers).includes(p)?'checked':''}>${p==='bkash'?'bKash':label(p)}</label>`).join('')}</div></div>`+reasonField(),'admin/merchants/'+rid,{status:m.status});}
 if(a==='merchant-key')return formModal('Issue merchant API key',reasonField(),'admin/merchants/'+rid+'/keys',{},'Issue key',r=>secretModal('Merchant API key',r.key,'Keep this key on the merchant server. It will not be shown again.'));
 if(a==='webhook-config')return formModal('Configure merchant webhook',hidden('merchant_id',rid)+input('Public HTTPS callback URL','url',state.endpoints.find(e=>e.merchant_id===rid)?.url||'','url')+reasonField(),'admin/webhook-endpoints',{},'Save endpoint',r=>secretModal('Webhook signing secret',r.secret,'Verify HMAC-SHA256 signatures over timestamp + dot + raw request body. Saving rotates the secret.'));
 if(a==='destination-request')return formModal('Request settlement destination change',input('New payout destination','destination')+reasonField(),'admin/merchants/'+rid+'/destination',{},'Request approval');
 if(a==='destination-approve')return formModal('Approve settlement destination',reasonField(),'admin/destinations/'+rid+'/approve',{},'Approve destination');
 if(a==='new-user')return formModal('Add recharge user',input('Full name','name')+input('Mobile number','number','','tel'),'admin/users');
 if(a==='user-status'){const u=byId('users',rid);return formModal('Update user status',select('Status','status',opts(['active','suspended']))+reasonField(),'admin/users/'+rid,{status:u.status});}
 if(a==='new-payment'||a==='new-recharge'){
  if(!state.accounts.some(a=>a.status==='active'))throw new Error('Activate a healthy receiving account first');
  return formModal(a==='new-recharge'?'Create test recharge':'Create test payment',hidden('beneficiary_type',a==='new-recharge'?'user':'merchant')+(a==='new-recharge'?hidden('user_id',rid):'')+input('Order ID','order_id','TEST-'+Date.now())+select('Merchant','merchant_id',merchantOptions())+select('Central receiving account','account_id',accountOptions())+input('Amount (BDT)','amount','','text','Exact amount expected from the customer.'),'payments',{},'Create request');
 }
 if(a==='claim-payment')return formModal('Submit customer payment details',input('Full sender number','sender','','tel')+input('Transaction ID','transaction'),'payments/'+rid+'/claim',{},'Check payment',r=>toast(r.status==='verified'?'Payment verified and ledger credited':'Waiting for matching receipt evidence'));
 if(a==='review'){
  const r=byId('reviews',rid),notes=state.notes.filter(n=>n.review_id===rid);
  const f=formModal('Investigate '+r.id.slice(0,8),`<div class="info-strip warning">${esc(r.category)} · ${badge(r.status)}</div>${notes.map(n=>`<div class="note"><small>${esc(n.actor)} · ${date(n.created)}</small>${esc(n.note)}</div>`).join('')}${select('Action','action',opts([['note','Add investigation note'],...(can('collection')?[['retry','Reparse / retry matching'],...(r.entity_type==='payment'?[['reject','Reject payment claim']]:[])]:[]),...(state.administrators.length?[['assign','Assign administrator']]:[])]))}${select('Assignee','assignee',opts(state.administrators.map(a=>[a.id,a.name])))}${reasonField()}`,'admin/reviews/'+rid,{},'Apply action');return f;
 }
 if(a==='new-settlement')return formModal('Prepare merchant settlement',select('Merchant','merchant_id',merchantOptions())+input('Payout amount (BDT)','amount')+reasonField(),'admin/settlements',{},'Reserve funds');
 if(a==='settlement-action'){const s=byId('settlements',rid);return formModal('Manage settlement',hidden('version',s.version)+`<div class="info-strip">${money(s.amount)} · ${esc(s.destination)}</div>`+select('Action','action',opts(s.status==='reserved'?[['approve','Approve — different administrator required'],['cancel','Cancel and release funds']]:s.status==='uncertain'?[['resolve_paid','Resolve with confirmed payout evidence'],['resolve_failed','Resolve with independent failure evidence']]:[['paid','Record completed external payout'],['uncertain','Mark external outcome uncertain'],['cancel','Cancel before external execution']]))+input('External payout transaction ID','external_trx','','text','Required only to record a paid settlement.',true)+input('Payout evidence','evidence','','text','Required for completed or uncertain payout resolution.',true)+reasonField(),'admin/settlements/'+rid,{},'Apply action');}
 if(a==='new-adjustment')return formModal('Request finance adjustment',select('Merchant','merchant_id',merchantOptions())+select('Direction','direction',opts(['credit','debit']))+input('Amount (BDT)','amount')+textarea('Supporting evidence','evidence')+reasonField(),'admin/adjustments',{},'Request approval');
 if(a==='adjustment-approve')return formModal('Approve finance adjustment',`<p>A different administrator must approve this request.</p>${reasonField()}`,'admin/adjustments/'+rid+'/approve',{},'Approve posting');
 if(a==='new-reconciliation')return formModal('Record collection reconciliation',select('Receiving account','account_id',accountOptions())+input('Statement day','day',today(),'date')+input('Total incoming statement amount (BDT)','statement_amount')+textarea('Statement evidence / note','note'),'admin/reconciliation');
 if(a==='export-ledger'){const result=await api('admin/export',{reason:'Administrator ledger CSV export'});const rows=[['created','kind','source','account','amount_poisha'],...result.rows.map(r=>[r.created,r.kind,r.source,r.account,r.amount])];const csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download='kpay-ledger-'+today()+'.csv';a.click();URL.revokeObjectURL(url);await refresh();return toast('Ledger export downloaded');}
 if(a==='account-security'){showModal('Account security',`<div class="info-strip">Authenticator MFA: ${badge(state.actor.mfa_enabled?'active':'paused')}</div><p>Authenticator-enabled accounts require a fresh code to sign in. Confirm again after five minutes before privileged changes.</p><div class="actions">${action(state.actor.mfa_enabled?'security-step-up':'security-start',state.actor.mfa_enabled?'Confirm authenticator':'Set up authenticator','','','shield')}</div>`);modal.querySelector('[data-action]').onclick=()=>handleAction(modal.querySelector('[data-action]').dataset.action,'').catch(e=>toast(e.message));return;}
 if(a==='security-step-up')return formModal('Confirm authenticator',input('Six-digit authenticator code','otp'),'admin/security/step-up',{},'Confirm code');
 if(a==='security-start'){const result=await api('admin/security/start',{});return formModal('Enable authenticator MFA',`<p>Add this secret to your authenticator app using a time-based six-digit code, then enter the code below.</p><div class="secret-box">${esc(result.secret)}</div>${input('Six-digit authenticator code','otp')}`,'admin/security/confirm',{},'Enable MFA');}
 if(a==='new-admin')return formModal('Add team administrator',input('Full name','name')+input('Email address','email','','email')+select('Role','role',opts(['operations','finance','support','owner']))+(authConfig.neon?'':input('Initial password','password','','password','At least 12 characters.'))+reasonField(),'admin/administrators');
 if(a==='admin-status'){const u=byId('administrators',rid);return formModal('Change administrator status',select('Status','status',opts(['active','suspended']))+reasonField(),'admin/administrators/'+rid,{status:u.status});}
 if(a==='webhook-retry')return formModal('Queue signed event redelivery',reasonField(),'admin/webhooks/'+rid+'/retry',{},'Queue redelivery');
}
async function viewDetail(type,rid){
 const d=state.actor.kind==='merchant'&&type==='merchants'?byId('merchants',rid):state.actor.kind==='merchant'&&type==='payments'?await api('payments/'+rid):await api('admin/detail/'+type+'/'+rid);
 const exclude=['message','pattern','sample','claims','decisions','receipt','entries','attempts','providers'];
 const fields=Object.entries(d).filter(([k,v])=>!exclude.includes(k)&&v!==null&&typeof v!=='object').map(([k,v])=>`<div class="detail-field"><span>${esc(label(k))}</span><strong>${esc(['amount','fee','minimum','maximum','daily_limit'].includes(k)?money(v):k==='created'||k==='expires'?date(v):v)}</strong></div>`).join('');
 let extra='';
 if(type==='templates'){extra=`<h3 class="subtitle">Matching pattern</h3><pre>${esc(d.pattern)}</pre><h3>Saved sample</h3><pre>${esc(d.sample)}</pre><h3>Test fixtures</h3>${state.fixtures.filter(f=>f.template_id===rid).map(f=>`<div class="note"><small>${esc(label(f.expected))}</small>${esc(f.message)}</div>`).join('')}`;}
 if(type==='sms')extra='<h3 class="subtitle">Restricted raw evidence</h3><pre>'+esc(d.message)+'</pre><h3>Parse history</h3>'+d.attempts.map(a=>'<pre>'+esc(a.result)+'</pre>').join('');
 if(type==='payments')extra=`<h3 class="subtitle">Verification timeline</h3><div class="timeline">${(d.claims||[]).map(c=>`<div class="timeline-item">Claim submitted · ${esc(c.trx)} · ${esc(mask(c.sender))}<small>${date(c.created)}</small></div>`).join('')}${(d.decisions||[]).map(c=>`<div class="timeline-item">${badge(c.outcome)} ${esc(c.reason)}<small>${date(c.created)}</small></div>`).join('')}</div>${d.status!=='verified'&&can('collection')?action('claim-payment','Submit test claim',rid,'','check'):''}`;
 if(type==='ledger')extra=`<div class="ledger-sum">Balanced entries · Net ${money(d.entries.reduce((s,e)=>s+e.amount,0))}</div><div class="wide"><table><thead><tr><th>Account</th><th>Posting (BDT)</th></tr></thead><tbody>${d.entries.map(e=>td(esc(e.account),money(e.amount))).join('')}</tbody></table></div>`;
 if(type==='merchants'&&can('*'))extra=`<h3 class="subtitle">API keys</h3>${state.keys.filter(k=>k.merchant_id===rid).map(k=>`<div class="health-row"><code>${esc(k.prefix)}••••</code>${badge(k.status)}${k.status==='active'?action('revoke-key','Revoke',k.id,'danger small'):''}</div>`).join('')}`;
 showModal(({ledger:'Ledger posting',sms:'SMS evidence',payments:'Payment',accounts:'Receiving account',devices:'Agent device',templates:'SMS template',users:'Recharge user',merchants:'Merchant',settlements:'Settlement'}[type]||label(type))+' details',`<div class="detail-grid">${fields}</div>${extra}`);
 modal.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{modal.close();handleAction(b.dataset.action,b.dataset.id).catch(e=>toast(e.message));});
 modal.querySelectorAll('[data-action="revoke-key"]').forEach(b=>b.onclick=()=>{formModal('Revoke merchant API key',reasonField(),'admin/keys/'+b.dataset.id+'/revoke',{},'Revoke key');});
}
async function initialize(){try{authConfig=await api('auth/config');}catch{}if(token||authConfig.neon){app.innerHTML='<div class="loading-view">Loading your workspace…</div>';await refresh(true);}else login();}
initialize();

window.addEventListener('hashchange',()=>{const next=decodeURIComponent(location.hash.slice(1));if(state&&next&&next!==page)go(next);});
